import {makeGameSounds,sparkle} from './interactions.mjs';
import {afterNarration} from './narration.mjs';
export const artPalette=[{id:'red',name:'Red',hex:'#ef746b',symbol:'●'},{id:'yellow',name:'Yellow',hex:'#f4cd57',symbol:'★'},{id:'blue',name:'Blue',hex:'#71a9e0',symbol:'◆'},{id:'green',name:'Green',hex:'#79b88a',symbol:'▲'},{id:'orange',name:'Orange',hex:'#efa160',symbol:'♥'},{id:'purple',name:'Purple',hex:'#b695d1',symbol:'✚'}];
export function artGuide(type,level){return {drawing:'Let’s draw! Choose a crayon and move your finger across the paper. You can make anything you like.',fill:'Choose a color, then tap a part of the flower. Color every part with your favorite colors.',number:level==='preschool'?'Match the numbers one to three with the crayons. Tap a part of the butterfly with the same number.':'Match the numbers one to six with the crayons. Tap a part of the butterfly with the same number.',mirror:'This is the mirror garden! Draw on one side and watch the other side get color. Choose Color Fill to color both wings together.'}[type]}
function artRegions(type,level){
 if(type==='drawing')return [];
 if(type==='fill')return [...Array.from({length:6},(_,i)=>{const angle=i*Math.PI/3;const x=300+80*Math.cos(angle),y=155+80*Math.sin(angle);return {id:'petal-'+i,shape:`<ellipse cx="${x}" cy="${y}" rx="47" ry="60" transform="rotate(${i*60+90} ${x} ${y})"/>`,x,y,color:artPalette[i].id}}),{id:'leaf-left',shape:'<path d="M295 300 Q190 240 205 310 Q255 347 295 300Z"/>',x:242,y:303,color:'green'},{id:'leaf-right',shape:'<path d="M305 300 Q410 240 395 310 Q345 347 305 300Z"/>',x:358,y:303,color:'green'},{id:'center',shape:'<circle cx="300" cy="155" r="43"/>',x:300,y:155,color:'yellow'}];
 const regions=[{id:'left-top',shape:'<path d="M292 172 C250 10 70 12 100 143 C117 202 225 196 292 172Z"/>',x:190,y:110,color:'red',pair:'right-top'},{id:'right-top',shape:'<path d="M308 172 C350 10 530 12 500 143 C483 202 375 196 308 172Z"/>',x:410,y:110,color:'red',pair:'left-top'},{id:'left-bottom',shape:'<path d="M292 183 C190 159 86 235 150 309 C204 362 268 287 292 183Z"/>',x:213,y:255,color:'blue',pair:'right-bottom'},{id:'right-bottom',shape:'<path d="M308 183 C410 159 514 235 450 309 C396 362 332 287 308 183Z"/>',x:387,y:255,color:'blue',pair:'left-bottom'}];
 if(level==='kindergarten')regions.push(...[{id:'spot-left-top',x:194,y:99,color:'yellow',pair:'spot-right-top'},{id:'spot-right-top',x:406,y:99,color:'yellow',pair:'spot-left-top'},{id:'spot-left-bottom',x:208,y:255,color:'purple',pair:'spot-right-bottom'},{id:'spot-right-bottom',x:392,y:255,color:'orange',pair:'spot-left-bottom'}].map(r=>({...r,shape:`<ellipse cx="${r.x}" cy="${r.y}" rx="28" ry="34"/>`})));
 if(type==='number'&&level==='kindergarten'){
  // These label anchors sit on open wing areas, outside the later spot shapes.
  const anchors={'left-top':[150,110],'right-top':[450,110],'left-bottom':[250,235],'right-bottom':[350,235]};
  for(const region of regions)if(anchors[region.id])[region.x,region.y]=anchors[region.id];
 }
 regions.push({id:'body',shape:'<ellipse cx="300" cy="188" rx="14" ry="91"/>',x:300,y:184,color:level==='preschool'?'yellow':'green'});return regions;
}
export function newArt(type,level){return {type,level,regions:artRegions(type,level),strokes:[],fills:{},undo:[],redo:[],outcome:'changed'}}
export function mirrorPoints(points){return points.map(p=>({x:600-p.x,y:p.y}))}
export function artComplete(s){return s.type==='drawing'?s.strokes.some(x=>x.color!=='erase'):s.type==='mirror'?s.strokes.some(x=>x.color!=='erase')||Object.keys(s.fills).length>0:s.regions.every(r=>s.fills[r.id])}
export function artMove(s,a){
 if(a.type==='undo'||a.type==='redo'){const from=a.type==='undo'?'undo':'redo',to=from==='undo'?'redo':'undo';if(!s[from].length)return s;const snap=s[from].at(-1);return {...s,...snap,[from]:s[from].slice(0,-1),[to]:[...s[to],{strokes:s.strokes,fills:s.fills}],outcome:'changed'}}
 let strokes=s.strokes,fills=s.fills;
 if(a.type==='stroke'){
  if(!['drawing','mirror'].includes(s.type)||!Array.isArray(a.points)||!a.points.length||!a.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y))||(!artPalette.some(c=>c.id===a.color)&&a.color!=='erase'))return s;
  if(strokes.length>=300)return {...s,outcome:'limit'};
  strokes=[...strokes,{points:a.points.slice(0,1200).map(p=>({x:Math.max(0,Math.min(600,p.x)),y:Math.max(0,Math.min(360,p.y))})),color:a.color,size:Math.max(4,Math.min(40,Number(a.size)||12))}];
 }else if(a.type==='fill'){
  const r=s.regions.find(r=>r.id===a.id);if(!r||!artPalette.some(c=>c.id===a.color))return s;
  if(s.type==='number'&&a.color!==r.color)return {...s,outcome:'wrong'};
  if(s.fills[r.id]===a.color)return s;
  fills={...fills,[r.id]:a.color};if(s.type==='mirror'&&r.pair)fills[r.pair]=a.color;
 }else if(a.type==='clear'){if(!strokes.length&&!Object.keys(fills).length)return s;strokes=[];fills={}}else return s;
 return {...s,strokes,fills,undo:[...s.undo,{strokes:s.strokes,fills:s.fills}].slice(-60),redo:[],outcome:'changed'};
}
function strokeSvg(stroke,mirror=false){const c=stroke.color==='erase'?'#fffdf7':artPalette.find(c=>c.id===stroke.color)?.hex??'#333';const one=points=>points.length===1?`<circle cx="${points[0].x}" cy="${points[0].y}" r="${stroke.size/2}" fill="${c}"/>`:`<polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${c}" stroke-width="${stroke.size}" stroke-linecap="round" stroke-linejoin="round"/>`;return one(stroke.points)+(mirror?one(mirrorPoints(stroke.points)):'')}
function artContent(s,interactive=false){
 const butterfly=!['drawing','fill'].includes(s.type);
 return `<rect width="600" height="360" fill="#fffdf7"/>${s.type==='fill'?'<path d="M300 160V345" stroke="#79b88a" stroke-width="13"/>':''}${butterfly?'<path d="M298 112 Q265 70 273 65 M302 112 Q335 70 327 65" stroke="#58644e" stroke-width="5" fill="none" stroke-linecap="round"/>':''}`+s.regions.map(r=>{const c=artPalette.find(c=>c.id===s.fills[r.id]),expected=artPalette.findIndex(c=>c.id===r.color)+1;return `<g ${interactive?`data-art-region="${r.id}" role="button" tabindex="0" aria-label="${s.type==='number'?'Numbered area '+expected:'Area '+(r.id.startsWith('petal-')?'petal '+(Number(r.id.split('-')[1])+1):({'left-top':'upper left wing','right-top':'upper right wing','left-bottom':'lower left wing','right-bottom':'lower right wing','spot-left-top':'upper left circle','spot-right-top':'upper right circle','spot-left-bottom':'lower left circle','spot-right-bottom':'lower right circle','body':'butterfly body','center':'flower center','leaf-left':'left leaf','leaf-right':'right leaf'}[r.id]??r.id))}${c?', color '+c.name:''}"`:''} fill="${c?.hex??'#f1f0e6'}" stroke="#65715d" stroke-width="3" stroke-linejoin="round">${r.shape}${s.type==='number'?`<text x="${r.x}" y="${r.y+6}" text-anchor="middle" fill="#364536" stroke="none" font-size="28" font-family="sans-serif" font-weight="bold" pointer-events="none">${c?'✓':expected}</text>`:''}</g>`}).join('')+`<g class="art-strokes" pointer-events="none">${s.strokes.map(st=>strokeSvg(st,s.type==='mirror')).join('')}</g>`;
}
export function artSvg(s){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 360" width="1200" height="720">${artContent(s)}</svg>`}
export function downloadArt(state,filename='Taman-Main-artwork.svg',doc=document){const url=URL.createObjectURL(new Blob([artSvg(state)],{type:'image/svg+xml'}));const link=doc.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
export function mountArtGame({activity:a,container,onSuccess,onMistake,speak,soundEnabled=()=>true,artSession=null}){
 let s=artSession?.initialState??newArt(a.game,a.level),color='red',size=12,tool=a.game==='fill'||a.game==='number'?'fill':'draw',draft=null,pointer=null,disposed=false,won=false,cancelFinish=()=>{},keyboard=false,cursor={x:150,y:180};
 const sounds=makeGameSounds(soundEnabled),q=sel=>container.querySelector(sel),all=sel=>[...container.querySelectorAll(sel)];
 const palette=a.game==='number'&&a.level==='preschool'?artPalette.slice(0,3):artPalette;
 container.innerHTML=`<div class="art-game art-${a.game}"><div class="art-lead"><span aria-hidden="true">🐰</span><p>${artGuide(a.game,a.level)}</p></div><div class="art-palette" aria-label="Choose a crayon">${palette.map((c,i)=>`<button class="art-swatch" data-art-color="${c.id}" aria-label="${a.game==='number'?'Number '+(i+1)+', ':''}${c.name}, symbol ${c.symbol}" aria-pressed="${i===0}" style="--paint:${c.hex}"><i>${a.game==='number'?i+1:c.symbol}</i><span>${c.name}</span></button>`).join('')}</div>${['drawing','mirror'].includes(a.game)?`<div class="art-tools" aria-label="Drawing tools"><button class="chip" data-art-tool="draw" aria-pressed="true">🖍 Crayon</button><button class="chip" data-art-tool="erase" aria-pressed="false">Eraser</button>${a.game==='mirror'?'<button class="chip" data-art-tool="fill" aria-pressed="false">▧ Color Fill</button>':''}<label>Size <select id="art-size"><option value="6">Small</option><option value="12" selected>Medium</option><option value="24">Large</option></select></label></div>`:''}<div class="art-paper"><svg id="art-board" viewBox="0 0 600 360" role="group" tabindex="0" aria-label="Paper for ${a.game==='mirror'?'mirror drawing':'coloring'}. Press Enter to start or stop drawing with the keyboard. Use the arrow keys to move the crayon."></svg>${a.game==='mirror'?'<span class="mirror-line" aria-hidden="true"></span><span class="mirror-label" aria-hidden="true">↔ MIRROR</span>':''}</div><p class="art-status" role="status" aria-live="polite"></p><div class="art-actions"><button class="chip" id="art-undo">↶ Undo</button><button class="chip" id="art-redo">↷ Redo</button><button class="chip" id="art-clear">New paper</button><button class="chip" id="art-gallery-save">Save to My Artwork</button><button class="chip" id="art-save">↓ Download SVG</button><button class="button" id="art-finish">Finish artwork ✓</button></div><p class="art-storage-status" role="status" aria-live="polite"></p><small class="art-note">${['drawing','mirror'].includes(a.game)?'Keyboard: focus the paper, press Enter to draw, then use the arrow keys. ':''}Artwork is saved automatically in this profile. Check the save status before closing. Download an SVG for a backup.</small></div>`;
 const board=q('#art-board');
 function storageStatus(note){const el=q('.art-storage-status');if(!el)return;el.classList.toggle('save-failed',note.state==='error');el.textContent=note.state==='saved'?'✓ Saved to My Artwork. You can open it again offline.':note.state==='pending'?'Saving to My Artwork…':note.state==='empty'?'New paper. Your earlier picture is still in My Artwork.':note.result?.reason==='conflict'?'This artwork changed in another tab. Download an SVG to keep your changes, then reopen it from the gallery.':'Not saved yet. Storage may be full or unavailable. Try Save to My Artwork again, or download an SVG before closing.'}
 if(artSession)artSession.onStatus=storageStatus;
 q('.art-storage-status').textContent=artSession?.initialState?'✓ Saved to My Artwork. You can keep creating.':'Start creating. Your artwork will be saved automatically in this profile.';
 function tell(t){q('.art-status').textContent=t}
 function paint(){const focused=container.ownerDocument.activeElement?.getAttribute('data-art-region');board.innerHTML=artContent(s,true)+(draft?`<g pointer-events="none">${strokeSvg({points:draft,color:tool==='erase'?'erase':color,size},s.type==='mirror')}</g>`:'')+(keyboard?`<circle cx="${cursor.x}" cy="${cursor.y}" r="8" fill="none" stroke="#253d31" stroke-dasharray="3 2" pointer-events="none"/>`:'');if(focused)q(`[data-art-region="${focused}"]`)?.focus();q('#art-undo').disabled=!s.undo.length||won;q('#art-redo').disabled=!s.redo.length||won;q('#art-clear').disabled=won;q('#art-finish').disabled=won||!artComplete(s);q('#art-save').disabled=!artComplete(s)&&!s.strokes.length&&!Object.keys(s.fills).length;q('#art-gallery-save').disabled=q('#art-save').disabled;
  all('[data-art-region]').forEach(el=>{el.tabIndex=tool==='fill'?0:-1;el.onclick=()=>fill(el.dataset.artRegion);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();fill(el.dataset.artRegion)}}});
 }
 function move(action){if(disposed||won)return;const before=s;s=artMove(s,action);paint();if(s.strokes!==before.strokes||s.fills!==before.fills)artSession?.change(s);if(s.outcome==='wrong'){onMistake();tell('Find the number that matches your crayon. You can try again.');speak('Let’s try again.');return}if(s.outcome==='limit'){tell('Your paper is full of ideas! Save your picture or start a new one.');return}if(action.type==='fill'){sounds.play('drop');tell(s.type==='number'?`${Object.keys(s.fills).length} of ${s.regions.length} areas matched.`:s.type==='mirror'?'Both sides get color. Just like a mirror!':`${Object.keys(s.fills).length} of ${s.regions.length} parts colored.`)}}
 function fill(id){if(tool==='fill')move({type:'fill',id,color})}
 function pos(e){const r=board.getBoundingClientRect();return {x:Math.max(0,Math.min(600,(e.clientX-r.left)*600/r.width)),y:Math.max(0,Math.min(360,(e.clientY-r.top)*360/r.height))}}
 function commit(){if(!draft)return;const points=draft;draft=null;move({type:'stroke',points,color:tool==='erase'?'erase':color,size})}
 board.onpointerdown=e=>{if(won||tool==='fill'||pointer!==null||e.button!==0)return;e.preventDefault();keyboard=false;pointer=e.pointerId;board.setPointerCapture(pointer);draft=[pos(e)];paint()};
 board.onpointermove=e=>{if(pointer!==e.pointerId||!draft)return;const p=pos(e),last=draft.at(-1);if(Math.hypot(p.x-last.x,p.y-last.y)<2)return;if(draft.length<1200)draft.push(p);paint()};
 board.onpointerup=e=>{if(pointer!==e.pointerId)return;pointer=null;commit()};
 board.onpointercancel=()=>{pointer=null;draft=null;paint()};
 board.onkeydown=e=>{if(e.target!==board||tool==='fill'||won)return;if(e.key==='Enter'){e.preventDefault();keyboard=!keyboard;if(keyboard){draft=[{...cursor}];tell('Crayon ready. Use the arrow keys, then press Enter to stop.')}else commit();paint()}else if(e.key.startsWith('Arrow')){e.preventDefault();cursor={x:Math.max(0,Math.min(600,cursor.x+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0))),y:Math.max(0,Math.min(360,cursor.y+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0)))};if(keyboard&&draft?.length<1200)draft.push({...cursor});paint()}};
 all('[data-art-color]').forEach(b=>b.onclick=()=>{if(won)return;if(draft)commit();keyboard=false;color=b.dataset.artColor;if(tool==='erase')tool='draw';syncTools();paint();all('[data-art-color]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));tell('Crayon '+artPalette.find(c=>c.id===color).name+' selected.')});
 function syncTools(){all('[data-art-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artTool===tool)));board.classList.toggle('fill-mode',tool==='fill')}
 all('[data-art-tool]').forEach(b=>b.onclick=()=>{if(won)return;if(draft)commit();keyboard=false;tool=b.dataset.artTool;syncTools();paint()});
 if(q('#art-size'))q('#art-size').onchange=e=>{if(draft)commit();keyboard=false;size=Number(e.target.value);paint()};
 q('#art-undo').onclick=()=>{draft=null;keyboard=false;move({type:'undo'})};q('#art-redo').onclick=()=>move({type:'redo'});
 q('#art-clear').onclick=()=>{if(draft)commit();keyboard=false;if(artSession&&!artSession.flush().ok)return;artSession?.newArtwork();draft=null;move({type:'clear'});tell('New paper is ready. Press Undo to bring back your picture.')};
 q('#art-gallery-save').onclick=()=>{if(draft)commit();keyboard=false;paint();if(artSession)artSession.flush();};
 q('#art-save').onclick=()=>{if(draft)commit();keyboard=false;paint();downloadArt(s,'Taman-Main-'+a.game+'.svg',container.ownerDocument);tell('Your picture is ready to download as an SVG.')};
 q('#art-finish').onclick=()=>{if(won||!artComplete(s))return;if(artSession&&!artSession.flush().ok)return;won=true;keyboard=false;all('button,select').forEach(b=>b.disabled=!['art-save','art-gallery-save'].includes(b.id));sparkle(container);sounds.play('good');tell('Great exploring! You gave it a try!');cancelFinish=afterNarration(speak,'Great exploring! You gave it a try!',500,()=>{if(!disposed)onSuccess()})};
 paint();syncTools();speak(artGuide(a.game,a.level));
 const cleanup=()=>{if(disposed)return;if(draft)commit();artSession?.dispose();disposed=true;cancelFinish();sounds.close();board.onpointerdown=board.onpointermove=board.onpointerup=board.onpointercancel=board.onkeydown=null;draft=null};cleanup.flush=()=>{if(disposed)return;if(draft)commit();pointer=null;keyboard=false;return artSession?.flush()};cleanup.replay=()=>{if(!won&&!disposed)return speak(artGuide(a.game,a.level),true)};return cleanup;
}
